// Phase 4 / Module 17: APIs and Web Development.
// Examples run offline: a local http.server thread stands in for the network, and Flask/FastAPI are exercised with their test clients.
// Needs: requests, flask, fastapi, httpx (installed in the course's virtual environment). Judged tasks use the standard library only.
"use strict";
const { chain, graph, table, terminal, svgWrap, esc } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];
const tx = (x, y, s, size = 13, anchor = "middle") => `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" fill="currentColor" font-family="system-ui,sans-serif">${esc(s)}</text>`;

// A reusable local server used by several examples (kept as text so each example is a self-contained program).
const SERVER = `import json, threading\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import urlparse, parse_qs\n\nSTUDENTS = [{"id": 1, "name": "Asha"}, {"id": 2, "name": "Ravi"}]\nstate = {"flaky": 2}\n\nclass Handler(BaseHTTPRequestHandler):\n    def send_json(self, status, body, extra=None):\n        data = json.dumps(body).encode()\n        self.send_response(status)\n        self.send_header("Content-Type", "application/json")\n        self.send_header("Content-Length", str(len(data)))\n        for key, value in (extra or {}).items():\n            self.send_header(key, value)\n        self.end_headers()\n        self.wfile.write(data)\n    def do_GET(self):\n        url = urlparse(self.path)\n        query = parse_qs(url.query)\n        if url.path == "/students":\n            dept = query.get("name", [None])[0]\n            found = [s for s in STUDENTS if dept is None or s["name"] == dept]\n            self.send_json(200, found)\n        elif url.path == "/flaky":\n            if state["flaky"] > 0:\n                state["flaky"] -= 1\n                self.send_json(503, {"error": "busy"}, {"Retry-After": "1"})\n            else:\n                self.send_json(200, {"ok": True})\n        elif url.path == "/page":\n            page = int(query.get("n", ["1"])[0])\n            self.send_json(200, {"items": list(range(page * 3 - 2, page * 3 + 1)), "next": page + 1 if page < 3 else None})\n        elif url.path == "/whoami":\n            self.send_json(200, {"agent": self.headers.get("User-Agent"), "token": self.headers.get("Authorization")})\n        else:\n            self.send_json(404, {"error": "not found"})\n    def do_POST(self):\n        length = int(self.headers.get("Content-Length", 0))\n        payload = json.loads(self.rfile.read(length) or b"{}")\n        if "name" not in payload:\n            self.send_json(400, {"error": "name required"})\n        else:\n            student = {"id": len(STUDENTS) + 1, "name": payload["name"]}\n            STUDENTS.append(student)\n            self.send_json(201, student, {"Location": f"/students/{student['id']}"})\n    def log_message(self, *args):\n        pass\n\nserver = ThreadingHTTPServer(("127.0.0.1", 0), Handler)\nthreading.Thread(target=server.serve_forever, daemon=True).start()\nBASE = f"http://127.0.0.1:{server.server_port}"\n`;

