lessons.push({
  title: "REST APIs and JSON: Designing Resources and Responses",
  minutes: 55,
  learn: ["Explain REST and its constraints in practical terms", "Design resource URLs and choose methods and status codes", "Shape JSON responses, errors, filtering and pagination", "Implement a tiny REST handler in plain Python"],
  why: "Most backend jobs involve building or consuming REST APIs. Consistent design makes an API easy to use, cache, test and evolve.",
  realWorld: "<code>GET /students/7</code>, <code>POST /orders</code>, <code>DELETE /cart/items/3</code>: the vocabulary of every modern web and mobile app.",
  simple: "REST models everything as a <strong>resource</strong> with a URL (a noun) and uses the HTTP <strong>method</strong> as the verb. Representations (usually JSON) travel in the body, and the server keeps no client state between requests.",
  detail: `<h3>Resource-oriented URLs</h3>
${table(["Operation", "Request", "Success response", "Errors"], [["list", "<code>GET /students</code>", "200 + JSON list", "-"], ["read one", "<code>GET /students/7</code>", "200 + object", "404"], ["create", "<code>POST /students</code> + JSON body", "201 + object + <code>Location</code>", "400 / 422, 409"], ["replace", "<code>PUT /students/7</code>", "200 or 204", "404, 422"], ["change part", "<code>PATCH /students/7</code>", "200", "404, 422"], ["delete", "<code>DELETE /students/7</code>", "204 (no body)", "404"], ["relation", "<code>GET /students/7/courses</code>", "200 + list", "404"]])}
<h3>Design rules</h3>
<ul><li><strong>Nouns, plural, lower case</strong> in URLs (<code>/students</code>, not <code>/getStudents</code>). Nest only one or two levels.</li><li><strong>Filter, sort and paginate</strong> with query parameters: <code>/students?dept=CSE&amp;sort=-marks&amp;page=2&amp;per_page=20</code>.</li><li><strong>Version</strong> the API: <code>/v1/...</code>, so you can change it without breaking old clients.</li><li><strong>Consistent errors</strong>: <code>{"error": {"code": "not_found", "message": "Student 7 does not exist"}}</code> with the right status.</li><li><strong>Idempotency</strong>: PUT and DELETE can be retried safely; for POST use an idempotency key.</li><li><strong>JSON</strong> keys in one style (snake_case or camelCase), dates as ISO 8601 strings (<code>2026-11-03T10:00:00Z</code>), money as integers (paise) or strings.</li><li>Use <strong>HATEOAS</strong> links only if you need them; most APIs skip them.</li></ul>
<h3>REST constraints in plain words</h3>
<p>Client-server separation, stateless requests, cacheable responses, a uniform interface (resources + methods + representations), a layered system (proxies and gateways are invisible). &quot;RESTful&quot; in practice means &quot;follows these conventions&quot;; GraphQL and gRPC are alternatives for other needs.</p>`,
  syntax: { code: `# a tiny handler: (method, path, body) -> (status, json)\ndef handle(method, path, body=None): ...`, note: "Frameworks do exactly this routing for you." },
  diagram: graph("A resource and its methods", "The resource /students/7 connected to the five operations GET read, PUT replace, PATCH change, DELETE remove, plus POST on /students to create.", 700, 230,
    [{ id: "r", k: "term", t: "/students/7", x: 350, y: 115, w: 150, h: 46 }, { id: "g", k: "io", t: "GET  200", x: 110, y: 40, w: 130, h: 36 }, { id: "p", k: "io", t: "PUT  200/204", x: 110, y: 115, w: 150, h: 36 }, { id: "pa", k: "io", t: "PATCH  200", x: 110, y: 190, w: 140, h: 36 }, { id: "d", k: "io", t: "DELETE  204", x: 590, y: 115, w: 140, h: 36 }, { id: "c", k: "io", t: "POST /students  201", x: 560, y: 40, w: 200, h: 36 }],
    [{ from: "g", to: "r" }, { from: "p", to: "r" }, { from: "pa", to: "r" }, { from: "r", to: "d" }]),
  example: { code: `import json\n\nitems = {}\nnext_id = 1\n\ndef handle(method, path, body=None):\n    global next_id\n    parts = [p for p in path.split("/") if p]\n    if parts == ["items"]:\n        if method == "GET":\n            return 200, list(items.values())\n        if method == "POST":\n            if not body or "name" not in body:\n                return 422, {"error": "name is required"}\n            item = {"id": next_id, "name": body["name"]}\n            items[next_id] = item\n            next_id += 1\n            return 201, item\n        return 405, {"error": "method not allowed"}\n    if len(parts) == 2 and parts[0] == "items" and parts[1].isdigit():\n        key = int(parts[1])\n        if key not in items:\n            return 404, {"error": "not found"}\n        if method == "GET":\n            return 200, items[key]\n        if method == "PUT":\n            items[key] = {"id": key, "name": body["name"]}\n            return 200, items[key]\n        if method == "DELETE":\n            del items[key]\n            return 204, None\n        return 405, {"error": "method not allowed"}\n    return 404, {"error": "not found"}\n\nfor method, path, body in [("POST", "/items", {"name": "pen"}), ("POST", "/items", {}), ("GET", "/items/1", None), ("PUT", "/items/1", {"name": "gel pen"}), ("GET", "/items", None), ("DELETE", "/items/1", None), ("GET", "/items/1", None), ("PATCH", "/items", None)]:\n    status, payload = handle(method, path, body)\n    print(method, path, status, json.dumps(payload) if payload is not None else "")`, out: `POST /items 201 {"id": 1, "name": "pen"}\nPOST /items 422 {"error": "name is required"}\nGET /items/1 200 {"id": 1, "name": "pen"}\nPUT /items/1 200 {"id": 1, "name": "gel pen"}\nGET /items 200 [{"id": 1, "name": "gel pen"}]\nDELETE /items/1 204 \nGET /items/1 404 {"error": "not found"}\nPATCH /items 405 {"error": "method not allowed"}` },
  lineByLine: [["parts = [p for p in path.split(\"/\") if p]", "Turns the path into segments."], ["POST validates the body", "A missing required field is a client error: 422."], ["201 + the created object", "A successful creation returns the new resource."], ["DELETE returns 204 and no body", "Success with nothing to return."], ["405 for an unsupported method", "The path exists but not for that method."], ["404 for unknown id or path", "No such resource."]],
  dryRun: { intro: "Life of item 1:", headers: ["Call", "State after"], rows: [["POST name pen", "{1: pen}"], ["PUT name gel pen", "{1: gel pen}"], ["DELETE", "{}"], ["GET", "404"]] },
  realExample: { intro: "Pagination metadata: slice a list the way a list endpoint would.", code: `import json\ndata = list(range(1, 11))\ndef page(items, page_number, per_page):\n    start = (page_number - 1) * per_page\n    chunk = items[start:start + per_page]\n    return {"page": page_number, "per_page": per_page, "total": len(items), "items": chunk, "has_next": start + per_page < len(items)}\nprint(json.dumps(page(data, 2, 4)))\nprint(json.dumps(page(data, 3, 4)))`, out: `{"page": 2, "per_page": 4, "total": 10, "items": [5, 6, 7, 8], "has_next": true}\n{"page": 3, "per_page": 4, "total": 10, "items": [9, 10], "has_next": false}` },
  mistakes: ["Verbs in URLs (<code>/createUser</code>).", "Always returning 200, even for errors.", "Returning different error shapes.", "No pagination on list endpoints.", "Breaking existing clients without a new version."],
  practices: ["Design the URLs and examples before coding.", "Use plural nouns and correct methods and codes.", "Document with OpenAPI (later lessons)."],
  interview: ["What makes an API RESTful?", "PUT vs PATCH?", "How do you paginate?", "How do you version an API?"],
  practiceQs: ["Design endpoints for a library (books and loans).", "Which status for creating a duplicate email?", "Why return 204 for delete?", "What is idempotency?"],
  revision: ["Resources are nouns; methods are verbs.", "201 Created, 204 No Content, 404, 422, 405.", "Filter, sort and paginate with query parameters.", "Version the API; consistent errors."],
  hinglish: "REST mein har cheez ek resource hai jiska URL noun hota hai (/students/7) aur kaam method batata hai (GET, POST, PUT, DELETE). Sahi status code lautao: bana to 201, delete par 204, na mila to 404, galat data par 422. List ko pagination do.",
  quiz: [
    mcq("Which URL follows REST naming?", ["/getStudents", "/students", "/doStudentList", "/student/get/all"], 1, "Plural noun for the collection."),
    mcq("What does a successful DELETE usually return?", ["200 with body", "204 with no body", "201", "404"], 1, "There is nothing to return."),
    mcq("PUT versus PATCH?", ["PUT replaces the resource; PATCH changes part of it", "They are identical", "PATCH deletes", "PUT is read-only"], 0, "Replace versus partial update."),
    mcq("Which status for invalid input data?", ["200", "404", "422 (or 400)", "500"], 2, "A client error."),
    mcq("Why version an API (/v1)?", ["It is faster", "Changes will not break existing clients", "It is required by HTTP", "To hide it"], 1, "Old clients keep using v1.")
  ],
  tasks: [task("Mini REST router", "Standard input holds requests, one per line: POST /items NAME, GET /items/ID, DELETE /items/ID. Keep items in memory (ids start at 1). Print the status and body: POST prints 201 {\"id\": N, \"name\": \"NAME\"}; GET prints 200 with the same JSON or 404 {\"error\": \"not found\"}; DELETE prints 204 or 404 {\"error\": \"not found\"}. Use json.dumps for the JSON text.", "import sys, json\nitems, next_id = {}, 1\n# process the requests\n", `import sys, json\nitems, next_id = {}, 1\nfor line in sys.stdin:\n    parts = line.split()\n    if not parts:\n        continue\n    method, path = parts[0], parts[1]\n    if method == "POST":\n        item = {"id": next_id, "name": parts[2]}\n        items[next_id] = item\n        next_id += 1\n        print(201, json.dumps(item))\n        continue\n    key = int(path.rsplit("/", 1)[1])\n    if key not in items:\n        print(404, json.dumps({"error": "not found"}))\n    elif method == "GET":\n        print(200, json.dumps(items[key]))\n    else:\n        del items[key]\n        print(204)`, [["POST /items pen\nGET /items/1\nDELETE /items/1\nGET /items/1", "201 {\"id\": 1, \"name\": \"pen\"}\n200 {\"id\": 1, \"name\": \"pen\"}\n204\n404 {\"error\": \"not found\"}"], ["GET /items/5", "404 {\"error\": \"not found\"}"]], [["POST /items pen\nGET /items/1\nDELETE /items/1\nGET /items/1", "201 {\"id\": 1, \"name\": \"pen\"}\n200 {\"id\": 1, \"name\": \"pen\"}\n204\n404 {\"error\": \"not found\"}"], ["GET /items/5", "404 {\"error\": \"not found\"}"], ["POST /items a\nPOST /items b\nGET /items/2", "201 {\"id\": 1, \"name\": \"a\"}\n201 {\"id\": 2, \"name\": \"b\"}\n200 {\"id\": 2, \"name\": \"b\"}"], ["DELETE /items/1", "404 {\"error\": \"not found\"}"]])],
});

