  tasks: [task("Build the request", "Read a base URL, then a line of key=value pairs separated by spaces (query parameters, possibly empty values), then a token. Print the final URL with the parameters encoded in the order given (use urllib.parse.urlencode), then the header line Authorization: Bearer <token>.", "from urllib.parse import urlencode\nbase = input()\npairs = input().split()\ntoken = input()\n# print the URL and the header\n", `from urllib.parse import urlencode\nbase = input()\npairs = [tuple(p.split("=", 1)) for p in input().split()]\ntoken = input()\nquery = urlencode(pairs)\nprint(base + ("?" + query if query else ""))\nprint("Authorization: Bearer " + token)`, [["https://api.example.in/search\nq=python page=2\nabc123", "https://api.example.in/search?q=python&page=2\nAuthorization: Bearer abc123"], ["https://x.in/a\ncity=New%20Delhi\nt", "https://x.in/a?city=New%2520Delhi\nAuthorization: Bearer t"]], [["https://api.example.in/search\nq=python page=2\nabc123", "https://api.example.in/search?q=python&page=2\nAuthorization: Bearer abc123"], ["https://x.in/a\ncity=New%20Delhi\nt", "https://x.in/a?city=New%2520Delhi\nAuthorization: Bearer t"], ["https://x.in/a\na=1&b=2\nk", "https://x.in/a?a=1%26b%3D2\nAuthorization: Bearer k"], ["https://x.in\nname=a+b\nz", "https://x.in?name=a%2Bb\nAuthorization: Bearer z"]])],
